def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid_values[0][2]

    for k, (xi, yi, vi) in enumerate(grid_values[1:], 1):
        if xi == 0 and yi == 0:
            break
        for x in range(N):
            for y in range(N):
                if x == xi - 1 and y == yi - 1:
                    dp[xi-1][yi-1][k] = max(dp[xi-1][yi-1][k], dp[x][y][k-1] + vi)
                if x == xi - 1 and y < yi - 1:
                    dp[xi-1][y][k] = max(dp[xi-1][y][k], dp[x][y][k-1])
                if x < xi - 1 and y == yi - 1:
                    dp[x][yi-1][k] = max(dp[x][yi-1][k], dp[x][y][k-1])

    return dp[N-1][N-1][k]

