def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        sign = '+' if coeff > 0 else '-'
        if i == 0:
            term = f"{abs(coeff)}"
        else:
            if abs(coeff) == 1:
                coeff_str = ''
            else:
                coeff_str = f"{abs(coeff)}"
            if i == 1:
                var_str = 'x'
            else:
                var_str = f'x^{i}'
            term = f"{coeff_str}{var_str}"
        if sign == '+':
            if terms:
                terms.append(f"+{term}")
            else:
                terms.append(term)
        else:
            terms.append(term)
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    :param encoded: A string representing the encoded information.
    :param original: A string representing the original information corresponding to the encoded string.
    :param message: A string representing the encrypted message to be decoded.
    :return: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            mapping[enc_char] = orig_char

    if len(mapping) != len(set(encoded)):
        return "Failed"

    decoded_message = ''.join(mapping.get(char, char) for char in message)
    return decoded_message

def count_coprime_pairs(x0: int, y0: int) -> int:
    from math import gcd

    if x0 > y0:
        return 0

    quotient = y0 // x0
    count = 0

    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

