def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Create a boolean array to store the results of subproblems
    dp = [[False] * (V + 1) for _ in range(n + 1)]

    # Initialize the dp array for the base case (0 volume can be achieved with 0 items)
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the dp array using dynamic programming
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            if volumes[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - volumes[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    # Find the maximum volume that can be occupied
    for j in range(V, -1, -1):
        if dp[n][j]:
            max_occupied = j
            break

    # Return the minimum remaining space
    return V - max_occupied

def calculate_arrangements(n: int, m: int, a: List[int]) -> int:
    MOD = 10**6 + 7

    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(0, m + 1):
            for k in range(0, min(j, a[i - 1]) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

